import re
lines=[json.loads(l) for l in open('data/z52b/pass2/outcome_TO4.jsonl')]
out=[]
for r in lines:
    if r['mid'] in R: out.append(R.pop(r['mid']))
    else: out.append(r)
assert not R, R.keys()
with open('data/z52b/pass2/outcome_TO4.jsonl','w') as f:
    for r in out: f.write(json.dumps(r,ensure_ascii=False)+"\n")
print("replaced; lines:", len(out))
